// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 value, bytes memory data) public {
        vm.assume(caller != address(0));
        uint256 balanceBefore = address(c).balance;
        vm.deal(caller, value);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: value}("");
        if (success) {
            balanceBefore += value;
        }
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", address(0), 0, ""));
        assertTrue((caller == c.owner()) == ok);
    }
}

